using System;using System.Collections.Generic;using System.Text;
internal static partial class NativeBackground{
 static bool InputRuntimeReady(IntPtr h,long image,long block){if(!WholeEnabled||!InputAppearance.Load().Enabled)return true;try{long root=cachedInstance;for(int i=0;i<32;i++){long parent=Pointer(h,Pointer(h,root+8)+16);if(parent==0)break;root=parent;}if(WidgetClass(h,image,root)!="mmui::MainWindow")return false;int targets=BitConverter.ToInt32(Read(h,block+0xf008,4),0);if(targets<0||targets>28)return false;var queue=new Queue<long>();var seen=new HashSet<long>();queue.Enqueue(root);while(queue.Count>0&&seen.Count<2200){long obj=queue.Dequeue();if(!seen.Add(obj))continue;string cls=WidgetClass(h,image,obj);if(obj==cachedInstance||cls.Contains("ListView")||cls=="mmui::XTableView"||cls=="mmui::MessageView")continue;foreach(long child in WidgetChildren(h,obj))queue.Enqueue(child);if(cls!="mmui::ChatInputView")continue;long data=Pointer(h,obj+0x28);if((BitConverter.ToUInt32(Read(h,data+8,4),0)&32768)==0)continue;var rect=WidgetRect(h,obj);if(rect.Width<32||rect.Height<24)continue;long table=Pointer(h,obj+0xc0);if(Pointer(h,table+8)!=block+0x3f000)return false;long current=Pointer(h,obj+0x160);if(current==0)return false;bool found=false;for(int i=0;i<targets;i++){long at=block+0xf010+i*24;if(Pointer(h,at)==obj&&Pointer(h,at+16)==current){found=true;break;}}if(!found)return false;}return true;}catch{return false;}}
}
